-- Sprint 13 additive migration. Generate/review manually; never auto-apply.
create table public.tasks(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),title text not null,description text,status text not null check(status in('pending','in_progress','completed','cancelled')),priority text not null check(priority in('low','medium','high','urgent')),due_at timestamptz not null,reminder_at timestamptz,completed_at timestamptz,assigned_user_id uuid references auth.users(id),related_type text check(related_type in('property','lead','deal')),related_id uuid,recurrence jsonb,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,check((related_type is null)=(related_id is null)));
create table public.meetings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),title text not null,meeting_type text not null check(meeting_type in('internal','customer','builder','broker','follow_up')),starts_at timestamptz not null,ends_at timestamptz not null,status text not null default'scheduled' check(status in('scheduled','completed','cancelled')),assigned_user_id uuid references auth.users(id),related_type text check(related_type in('property','lead','deal')),related_id uuid,notes text,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,check(ends_at>starts_at),check((related_type is null)=(related_id is null)));
create table public.site_visits(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),property_id uuid not null references public.properties(id),lead_id uuid references public.leads(id),deal_id uuid references public.deals(id),assigned_agent_id uuid references auth.users(id),starts_at timestamptz not null,ends_at timestamptz,status text not null default'scheduled' check(status in('scheduled','completed','cancelled','no_show')),outcome text,notes text,created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1);
create table public.activity_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),event_type text not null,title text not null,description text,actor_id uuid references auth.users(id),related_type text,related_id uuid,metadata jsonb not null default'{}',occurred_at timestamptz not null default now());
create table public.calendar_entries(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),entry_type text not null check(entry_type in('task','meeting','site_visit')),source_id uuid not null,title text not null,starts_at timestamptz not null,ends_at timestamptz,status text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,version integer not null default 1,unique(entry_type,source_id));
create table public.task_saved_views(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),workspace_id uuid not null references public.workspaces(id),user_id uuid not null references auth.users(id),name text not null,filters jsonb not null default'{}',created_at timestamptz not null default now(),unique(workspace_id,user_id,name));
create index tasks_due_idx on public.tasks(organization_id,workspace_id,due_at)where deleted_at is null;create index meetings_start_idx on public.meetings(organization_id,workspace_id,starts_at)where deleted_at is null;create index visits_start_idx on public.site_visits(organization_id,workspace_id,starts_at)where deleted_at is null;create index activity_timeline_idx on public.activity_events(organization_id,workspace_id,occurred_at desc);create index calendar_range_idx on public.calendar_entries(organization_id,workspace_id,starts_at)where deleted_at is null;
alter table public.tasks enable row level security;alter table public.meetings enable row level security;alter table public.site_visits enable row level security;alter table public.activity_events enable row level security;alter table public.calendar_entries enable row level security;alter table public.task_saved_views enable row level security;
create or replace function public.can_use_operations(p_workspace uuid)returns boolean language sql stable security definer set search_path=public as $$select public.current_workspace_role(p_workspace)in('organization_owner','organization_admin','branch_manager','sales_manager','agent')$$;
create policy "tasks_workspace_read" on public.tasks for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "meetings_workspace_read" on public.meetings for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "site_visits_workspace_read" on public.site_visits for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "activity_workspace_read" on public.activity_events for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "calendar_workspace_read" on public.calendar_entries for select to authenticated using(public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);create policy "task_views_owner_read" on public.task_saved_views for select to authenticated using(user_id=auth.uid()and public.is_organization_member(organization_id)and public.current_workspace_role(workspace_id)is not null);
create or replace function public.create_operation_task(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not can_use_operations(p_workspace_id)then raise exception'insufficient task permission';end if;insert into tasks(organization_id,workspace_id,title,description,status,priority,due_at,assigned_user_id,related_type,related_id,created_by,updated_by)values(v_org,p_workspace_id,p_input->>'title',nullif(p_input->>'description',''),p_input->>'status',p_input->>'priority',(p_input->>'dueAt')::timestamptz,nullif(p_input->>'assignedUserId','')::uuid,nullif(p_input->>'relatedType',''),nullif(p_input->>'relatedId','')::uuid,auth.uid(),auth.uid())returning id into v_id;insert into calendar_entries(organization_id,workspace_id,entry_type,source_id,title,starts_at,status)values(v_org,p_workspace_id,'task',v_id,p_input->>'title',(p_input->>'dueAt')::timestamptz,p_input->>'status');insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(v_org,p_workspace_id,'task.created','Task created',auth.uid(),'task',v_id);return v_id;end$$;
create or replace function public.update_operation_task(p_task_id uuid,p_expected_version integer,p_input jsonb)returns void language plpgsql security definer set search_path=public as $$declare t tasks%rowtype;begin select*into t from tasks where id=p_task_id and deleted_at is null for update;if not found or not can_use_operations(t.workspace_id)then raise exception'insufficient task permission';end if;if t.version<>p_expected_version then raise exception'task changed by another user';end if;update tasks set title=p_input->>'title',description=nullif(p_input->>'description',''),status=p_input->>'status',priority=p_input->>'priority',due_at=(p_input->>'dueAt')::timestamptz,assigned_user_id=nullif(p_input->>'assignedUserId','')::uuid,related_type=nullif(p_input->>'relatedType',''),related_id=nullif(p_input->>'relatedId','')::uuid,updated_by=auth.uid(),updated_at=now(),version=version+1 where id=p_task_id;update calendar_entries set title=p_input->>'title',starts_at=(p_input->>'dueAt')::timestamptz,status=p_input->>'status',updated_at=now(),version=version+1 where entry_type='task'and source_id=p_task_id;end$$;
create or replace function public.complete_operation_task(p_task_id uuid,p_expected_version integer)returns void language plpgsql security definer set search_path=public as $$declare t tasks%rowtype;begin select*into t from tasks where id=p_task_id and deleted_at is null for update;if not found or not can_use_operations(t.workspace_id)then raise exception'insufficient task permission';end if;if t.version<>p_expected_version then raise exception'task changed by another user';end if;update tasks set status='completed',completed_at=now(),updated_by=auth.uid(),updated_at=now(),version=version+1 where id=p_task_id;update calendar_entries set status='completed',updated_at=now(),version=version+1 where entry_type='task'and source_id=p_task_id;insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(t.organization_id,t.workspace_id,'task.completed','Task completed',auth.uid(),'task',t.id);end$$;
create or replace function public.archive_operation_task(p_task_id uuid)returns void language plpgsql security definer set search_path=public as $$declare t tasks%rowtype;begin select*into t from tasks where id=p_task_id and deleted_at is null;if not found or not can_use_operations(t.workspace_id)then raise exception'insufficient task permission';end if;update tasks set deleted_at=now(),updated_by=auth.uid(),updated_at=now(),version=version+1 where id=p_task_id;update calendar_entries set deleted_at=now(),updated_at=now(),version=version+1 where entry_type='task'and source_id=p_task_id;end$$;
create or replace function public.schedule_operation_meeting(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not can_use_operations(p_workspace_id)then raise exception'insufficient meeting permission';end if;insert into meetings(organization_id,workspace_id,title,meeting_type,starts_at,ends_at,related_type,related_id,created_by,updated_by)values(v_org,p_workspace_id,p_input->>'title',p_input->>'meetingType',(p_input->>'startsAt')::timestamptz,(p_input->>'endsAt')::timestamptz,nullif(p_input->>'relatedType',''),nullif(p_input->>'relatedId','')::uuid,auth.uid(),auth.uid())returning id into v_id;insert into calendar_entries(organization_id,workspace_id,entry_type,source_id,title,starts_at,ends_at,status)values(v_org,p_workspace_id,'meeting',v_id,p_input->>'title',(p_input->>'startsAt')::timestamptz,(p_input->>'endsAt')::timestamptz,'scheduled');insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(v_org,p_workspace_id,'meeting.scheduled','Meeting scheduled',auth.uid(),'meeting',v_id);return v_id;end$$;
create or replace function public.schedule_operation_visit(p_workspace_id uuid,p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare v_org uuid;v_id uuid;begin select organization_id into v_org from workspace_members where workspace_id=p_workspace_id and user_id=auth.uid()and status='active';if v_org is null or not can_use_operations(p_workspace_id)then raise exception'insufficient visit permission';end if;if not exists(select 1 from properties where id=(p_input->>'propertyId')::uuid and organization_id=v_org and workspace_id=p_workspace_id and deleted_at is null)then raise exception'invalid property';end if;insert into site_visits(organization_id,workspace_id,property_id,lead_id,assigned_agent_id,starts_at,status,outcome,notes,created_by,updated_by)values(v_org,p_workspace_id,(p_input->>'propertyId')::uuid,nullif(p_input->>'leadId','')::uuid,nullif(p_input->>'assignedAgentId','')::uuid,(p_input->>'startsAt')::timestamptz,p_input->>'status',nullif(p_input->>'outcome',''),nullif(p_input->>'notes',''),auth.uid(),auth.uid())returning id into v_id;insert into calendar_entries(organization_id,workspace_id,entry_type,source_id,title,starts_at,status)values(v_org,p_workspace_id,'site_visit',v_id,'Property site visit',(p_input->>'startsAt')::timestamptz,p_input->>'status');insert into activity_events(organization_id,workspace_id,event_type,title,actor_id,related_type,related_id)values(v_org,p_workspace_id,'site_visit.scheduled','Site visit scheduled',auth.uid(),'site_visit',v_id);return v_id;end$$;
